/// <summary>
/// Data contract class as a response for service <c>METPickListService</c>
/// </summary>
[DataContractAttribute]
class METPickListResponseContract extends METBaseResponseContract
{
}

Method.Source:
    /// <summary>
    /// Contruct a new Response contract
    /// </summary>
    /// <param name = "_Result">Result of the lation</param>
    /// <param name = "_Message">Message Result</param>
    /// <returns>new contract</returns>
    public static METPickListResponseContract newFromParameters(METProcessingStatus _Result, Description255 _Message)
    {
        METPickListResponseContract PickListResponse = new METPickListResponseContract();

        PickListResponse.parmResult(enum2Symbol(enumNum(METProcessingStatus), enum2int(_Result)));
        PickListResponse.parmMessage(_Message);

        return PickListResponse;
    }
